#include <cassert>
#include "securezone/decision/DecisionEngine.h"
int main() { using namespace securezone::domain; securezone::decision::DecisionEngine engine; Detection p{"t","c",ObjectClass::Person}; Zone zone{"z","Danger","c",ZoneType::Dangerous}; AccessPolicy policy{"p","z",{"operator"},{MachineStatus::Stopped}}; MachineState stopped{"m",MachineStatus::Stopped}; Employee allowed{"e","Name","Operator",{"operator"}}; Employee wrong{"e","Name","Guest",{"guest"}};
 assert(engine.evaluate(p,zone,allowed,stopped,policy,false).type == AccessDecisionType::Allowed); assert(engine.evaluate(p,zone,allowed,stopped,policy,true).type == AccessDecisionType::Allowed); assert(engine.evaluate(p,zone,wrong,stopped,policy,true).type == AccessDecisionType::Violation); assert(engine.evaluate(p,zone,std::nullopt,stopped,policy,true).type == AccessDecisionType::UnknownIdentity); assert(engine.evaluate(p,zone,allowed,{"m",MachineStatus::Running},policy,true).type == AccessDecisionType::Violation); }
